-- Generated by node scripts/build-parallel-practice-migration.cjs.
-- Reuses canonical attempt/response storage; does not reopen diagnostic RPCs.
BEGIN;

CREATE OR REPLACE FUNCTION public.save_nur312_parallel_practice(
  p_action text,
  p_session_key text DEFAULT NULL,
  p_attempt_id uuid DEFAULT NULL,
  p_expected_revision integer DEFAULT NULL,
  p_item_id text DEFAULT NULL,
  p_answer integer DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
  v_keys constant jsonb := $bank$__BANK_KEYS__$bank$::jsonb;
  v_student uuid;
  v_attempt public.in_house_assessment_attempts%ROWTYPE;
  v_key jsonb;
  v_saved record;
  v_total integer;
  v_correct integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sign in to save this practice test.' USING ERRCODE = '42501';
  END IF;
  SELECT id INTO v_student FROM public.students WHERE auth_user_id=auth.uid();
  IF v_student IS NULL THEN
    RAISE EXCEPTION 'No student profile is linked to this account.' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.student_resources
    WHERE student_id=v_student AND url='nur312-exam2-parallel.html'
  ) THEN
    RAISE EXCEPTION 'This practice set is not assigned to your account. Ask your tutor to check the assignment.'
      USING ERRCODE = '42501';
  END IF;

  IF p_action='start' THEN
    SELECT * INTO v_saved FROM public.create_in_house_assessment_attempt(
      v_student,p_session_key,'nur312-exam2-parallel',
      'NUR 312 Exam 2 Clinical Judgment Practice · Parallel Set',
      'nur312-exam2-parallel-v1',jsonb_array_length(v_keys),false,
      jsonb_build_object('schemaVersion',1,'currentQuestion',0)
    );
    SELECT * INTO v_attempt FROM public.in_house_assessment_attempts WHERE id=v_saved.attempt_id;
    IF v_attempt.assessment_key <> 'nur312-exam2-parallel' THEN
      RAISE EXCEPTION 'Practice session belongs to another assessment.';
    END IF;
    RETURN jsonb_build_object('id',v_attempt.id,'checkpoint_revision',v_attempt.checkpoint_revision);
  END IF;

  SELECT * INTO v_attempt FROM public.in_house_assessment_attempts
  WHERE id=p_attempt_id AND student_id=v_student AND assessment_key='nur312-exam2-parallel'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Practice attempt not found for this account.' USING ERRCODE = '42501';
  END IF;

  IF p_action='answer' THEN
    IF p_expected_revision IS NULL OR p_expected_revision < 0 THEN
      RAISE EXCEPTION 'Practice response revision is required.';
    END IF;
    SELECT value INTO v_key FROM jsonb_array_elements(v_keys) WHERE value->>'id'=p_item_id;
    IF v_key IS NULL OR p_answer IS NULL OR p_answer NOT BETWEEN 0 AND 3 THEN
      RAISE EXCEPTION 'A valid practice question and answer are required.';
    END IF;
    SELECT * INTO v_saved FROM public.record_in_house_assessment_response(
      v_attempt.id,p_expected_revision,
      jsonb_build_object(
        'item_id',p_item_id,'item_source',v_key->>'source','question_type','mcq',
        'difficulty',(v_key->>'difficulty')::integer,'topic',v_key->>'topic',
        'selected_answer',p_answer,'correct_answer',(v_key->>'a')::integer,
        'is_correct',p_answer=(v_key->>'a')::integer
      ),
      jsonb_build_object('schemaVersion',1,'currentQuestion',v_attempt.total_questions),
      NULL
    );
    RETURN jsonb_build_object(
      'checkpointRevision',v_saved.checkpoint_revision,
      'totalQuestions',v_saved.total_questions,'correctQuestions',v_saved.correct_questions
    );
  ELSIF p_action='finish' THEN
    SELECT count(*),count(*) FILTER (WHERE is_correct) INTO v_total,v_correct
    FROM public.in_house_assessment_item_responses WHERE attempt_id=v_attempt.id;
    IF v_total <> jsonb_array_length(v_keys) THEN
      RAISE EXCEPTION 'Not all responses have saved. Keep this page open and retry the unsaved question.';
    END IF;
    PERFORM public.finalize_in_house_assessment_attempt(v_attempt.id,NULL,v_correct::numeric/v_total);
    RETURN jsonb_build_object('id',v_attempt.id,'totalQuestions',v_total,'correctQuestions',v_correct);
  END IF;
  RAISE EXCEPTION 'Practice action is not supported.';
END;
$$;

REVOKE ALL ON FUNCTION public.save_nur312_parallel_practice(text,text,uuid,integer,text,integer)
  FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.save_nur312_parallel_practice(text,text,uuid,integer,text,integer)
  TO authenticated;

COMMIT;
